import{_ as t,o,c as e,ai as p}from"./chunks/framework.BxxKhjs3.js";const a="/pub-blog/assets/image-20260514094404262.CJvtC2A7.png",r="/pub-blog/assets/image-20260514094029216.Bm3y-jk8.png",s="/pub-blog/assets/kimi.B9DeLFy6.jpg",i="/pub-blog/assets/image-20260514094137314.D0977xWu.png",u="/pub-blog/assets/image-20260514094222206.DOrq2xgi.png",g="/pub-blog/assets/deepseek.BNs70wUi.jpg",d="/pub-blog/assets/image-20260514094506815.Bn9CCgJo.png",q="/pub-blog/assets/capcut.D1iTmMCw.jpg",l="/pub-blog/assets/image-20260404153811993.DCT8eByA.png",P=JSON.parse(`{"title":"万少用9个AI工具，帮朋友完成了一个\\"不可能\\"的项目","description":"","frontmatter":{},"headers":[],"relativePath":"AI人工智能/要是没有AI 万少是不想也不可能完成这个任务的/要是没有AI 万少是不想也不可能完成这个任务的.md","filePath":"AI人工智能/要是没有AI 万少是不想也不可能完成这个任务的/要是没有AI 万少是不想也不可能完成这个任务的.md","lastUpdated":1778723494000,"__rawMarkdown":"# 万少用9个AI工具，帮朋友完成了一个\\"不可能\\"的项目\\n\\n> **要是没有AI，万少是不想也不可能完成这个任务的。**\\n\\n---\\n\\n![](assets/image-20260514094404262.png)\\n\\n## 一、一个电话引发的\\"不可能任务\\"\\n\\n上个月，万少的朋友老李突然给他打电话，声音里带着那种成年人特有的疲惫和焦虑。\\n\\n\\"兄弟，救命。\\"\\n\\n原来，他所在的集团突然下发了一个任务：每个子公司必须完成一个**AI创新项目**，而且要求全套交付——**系统、文档、PPT、讲解视频**，一样不能少。\\n\\n老李在一家传统制造业公司干了十年，连Excel函数都用不利索，更别说做什么AI系统了。他跟万少说：\\"集团领导说要'拥抱人工智能'，我连AI的A字怎么写都不知道。\\"\\n\\n更离谱的是，这个项目从下发到截止，**只有两周时间**。\\n\\n老李知道万少平时爱玩AI、折腾各种新工具，于是把希望寄托在了万少身上。\\n\\n万少听完沉默了五秒钟。\\n\\n说实话，这个任务量——系统开发+数字人制作+文档+PPT+视频——放在以前，就算是一个专业团队也得折腾一个月。\\n\\n但2026年了，AI工具已经多到眼花缭乱。也许，**用AI工具链的组合，真的能在两周内搞定这一切**？\\n\\n于是，一场\\"用AI造AI\\"的疯狂实验，就这样开始了。\\n\\n---\\n\\n## 二、阶段一：AI系统开发——Claude Code + Kimi\\n\\n### 第一个问题：系统从哪来？\\n\\n老李的项目需求很模糊——\\"做一个AI智能问答系统\\"。没有详细需求文档，没有设计稿，没有技术方案。\\n\\n放在以前，这至少需要一个月的需求调研+技术选型+开发测试。\\n\\n但现在，万少打开了 **Claude Code**。\\n\\n![](assets/image-20260514094029216.png)\\n\\nClaude Code 是 Anthropic 推出的一款AI编程助手（基于命令行/IDE插件使用，上图为其官网），跟普通的聊天机器人不一样，它可以直接操作你的代码仓库、运行命令、读写文件。简单说，**你说话，它写代码**。\\n\\n万少跟它说：\\"帮我做一个AI智能问答网站，要有前端界面，能调用大模型API回答问题，界面要简洁美观。\\"\\n\\n二十分钟后，一个完整的项目骨架就出来了：React前端 + Node.js后端 + 大模型API对接。\\n\\n但这还不够。万少需要让系统更\\"智能\\"——能处理文档上传、能记住对话历史、能根据上下文回答。\\n\\n这时候，**Kimi** 登场了。\\n\\n![Kimi 界面](assets/kimi.jpg)\\n\\nKimi 是国内月之暗面推出的大模型，它的特长是**超长上下文**——能一次性处理几十万字的文档。万少把 Claude 生成的代码丢给 Kimi，让它帮忙优化提示词工程、设计对话流程、甚至生成系统的知识库内容。\\n\\n**Claude 负责\\"搭骨架\\"，Kimi 负责\\"填血肉\\"。**\\n\\n\\n\\n---\\n\\n## 三、阶段二：数字人制作——GPT + 豆包 + 小米TTS\\n\\n### 第二个问题：集团要求\\"真人讲解视频\\"\\n\\n系统有了，但集团要求提交一段**讲解视频**——必须由项目负责人（也就是老李）出镜，介绍这个AI系统的功能和亮点。\\n\\n老李跟万少说：\\"让我对着镜头讲代码？不如杀了我。\\"\\n\\n确实，系统是万少做的，老李连系统里有几个页面都不知道，怎么讲？\\n\\n但集团的要求很明确：**真人声音+真人形象**，要看到\\"项目负责人亲自讲解\\"。\\n\\n于是万少想到了一个\\"曲线救国\\"的方案——**数字人**。\\n\\n**第一步：生成数字人形象**\\n\\n用 **GPT** 的图像生成功能，万少生成了一位\\"专业、靠谱、看起来像在制造业干了十年的中年男性\\"形象。为什么不用老李本人的照片？因为集团要求\\"正式形象\\"，而老李的微信头像还是五年前钓鱼时拍的。\\n\\n**第二步：让图片动起来**\\n\\n静态图片不行，要让它\\"说话\\"。万少用 豆包的图片转视频功能，把数字人图片做成了\\"念字动画\\"——就是嘴型会动、头会微微摆动的那种。\\n\\n![](assets/image-20260514094137314.png)\\n\\n**第三步：给数字人配声音**\\n\\n这是最关键的一步。视频需要\\"老李的声音\\"来讲解，但老李讲不出来。怎么办？\\n\\n万少找到了 **小米大模型的TTS（文本转语音）服务**。小米给开发者提供了免费的token额度，只需要把讲解稿输入进去，它就能生成自然流畅的中文语音。\\n\\n![](assets/image-20260514094222206.png)\\n\\n但这里有个问题：生成的声音是\\"标准男声\\"，不是老李的声音。\\n\\n别急，后面有**大招**。\\n\\n---\\n\\n## 四、阶段三：智能数据生成——DeepSeek\\n\\n### 第三个问题：系统里要有\\"真实数据\\"\\n\\n一个AI问答系统，不能只有空壳子。集团领导万一要现场提问呢？系统必须能给出像模像样的回答。\\n\\n但万少不可能手动录入几百条问答数据。\\n\\n这时候，**DeepSeek** 派上了大用场。\\n\\n![DeepSeek 界面](assets/deepseek.jpg)\\n\\nDeepSeek 是杭州深度求索推出的开源大模型，推理能力极强，网页版可以免费使用，API调用也有赠送额度。\\n\\n万少设计了一个自动化流程：\\n\\n1. 用 DeepSeek 生成\\"制造业常见AI问答对\\"——比如\\"什么是智能质检\\"、\\"AI怎么优化排产\\"等等\\n2. 让 DeepSeek 根据每个问题生成**专业、详细、有数据支撑**的回答\\n3. 把这些问答对自动写入系统的知识库\\n\\n一晚上，系统里多了**800多条高质量问答数据**，覆盖了智能制造、供应链优化、质量检测等十几个场景。\\n\\n更绝的是，万少让 DeepSeek 生成了一套**动态题目**——如果集团领导要\\"考\\"这个系统，系统能随机生成专业问题并给出标准答案。\\n\\n老李问万少：\\"这些数据靠谱吗？\\"\\n\\n万少说：\\"DeepSeek 写的，比你自己写的靠谱多了。\\"\\n\\n---\\n\\n## 五、阶段四：一键部署——腾讯EdgeOne\\n\\n![](assets/image-20260514094506815.png)\\n\\n### 第四个问题：系统要能\\"现场演示\\"\\n\\n集团评审是现场会，领导们会当场打开系统看效果。系统必须能**稳定访问、快速加载、看起来专业**。\\n\\n万少原本打算部署到自己的服务器上，但担心现场网络环境复杂，万一打不开就全完了。\\n\\n这时候，**腾讯EdgeOne** 派上了大用场。\\n\\n\\n\\nEdgeOne 是腾讯推出的边缘计算和CDN服务，简单说就是：把你的网站部署到全国各地的服务器节点上，用户访问时自动连接到最近的一个，**速度快、稳定性高**。\\n\\n更关键的是，它支持**自动化部署**。万少把代码推送到Git仓库，EdgeOne 自动拉取、构建、部署，整个过程相对快捷。\\n\\n而且 EdgeOne 自带HTTPS证书、DDoS防护、访问统计——**看起来就很\\"企业级\\"**。\\n\\n老李把系统链接发到集团群里的时候，附了一句：\\"我们的AI系统已上线，欢迎体验。\\"\\n\\n三分钟后，集团IT部的人在群里回了一个大拇指。\\n\\n---\\n\\n## 六、阶段五：文档与视频自动化——Kimi + CapCut + 剪映声音克隆\\n\\n### 第五个问题：全套交付物怎么搞？\\n\\n集团要求的是**全套交付**：系统、文档、PPT、讲解视频。\\n\\n系统有了，但文档和PPT怎么办？让老李写？他连Markdown是什么都不知道。\\n\\n**文档自动化：Kimi的\\"一键生成\\"**\\n\\n万少把系统的代码结构、功能说明、技术架构截图发给 Kimi，让它帮忙生成：\\n\\n- 一份**30页的技术白皮书**（Word格式）\\n- 一份**15页的汇报PPT**\\n- 一份**5000字的项目总结**\\n\\nKimi 花了大概十分钟，生成了全部内容。万少稍微调整了排版和格式，直接就能用。\\n\\n老李看到文档的时候惊呆了：\\"这写得比我自己还了解这个项目。\\"\\n\\n万少说：\\"废话，这项目本来就是AI做的，AI当然最了解。\\"\\n\\n**视频制作：CapCut + 剪映**\\n\\n现在到了最精彩的部分——**讲解视频**。\\n\\n前面说了，万少用数字人+小米TTS生成了\\"讲解音频\\"，但声音不是老李本人的。集团要求\\"项目负责人亲自讲解\\"，如果声音明显不是他的，那就露馅了。\\n\\n怎么办？\\n\\n**剪映的声音克隆功能，成了整个项目的\\"神来之笔\\"。**\\n\\n![剪映/CapCut界面](assets/capcut.jpg)\\n\\n剪映（国内版，海外版叫CapCut）最近上线了**声音克隆**功能。万少只需要让老李对着手机念一段1-2分钟的样本文字，剪映就能**克隆出他的声音**——音色、语调、甚至说话的习惯性停顿，都模仿得惟妙惟肖。\\n\\n> **技术伦理提示**：声音克隆涉及个人声音权益，使用前需获得本人明确授权。本文所述场景已获得当事人同意，仅供技术探讨。\\n\\n然后，万少把之前用小米TTS生成的\\"标准讲解稿\\"，用剪映的**声音克隆**重新生成了一遍。\\n\\n出来的效果？\\n\\n**完全是老李在说话。**\\n\\n万少把视频发给老李，老李听完回了三个问号：\\"这他妈是我？？？\\"\\n\\n万少说：\\"是'你'，但不是你说的。\\"\\n\\n最后，万少用 **剪映（CapCut）** 把数字人画面、克隆声音、系统录屏、字幕全部剪辑在一起，加了一个\\"科技感\\"的片头片尾。\\n\\n一条**5分钟的\\"项目负责人亲自讲解AI系统\\"视频**，就这样诞生了。\\n\\n\\n\\n---\\n\\n## 八、写在最后\\n\\n回头看这个项目，万少用了**9个AI工具**：\\n\\n| 工具 | 用途 |\\n|------|------|\\n| Claude Code | 开发AI系统 |\\n| Kimi | 代码优化、文档生成、PPT生成 |\\n| GPT | 数字人形象生成 |\\n| 即梦AI | 图片转视频（念字动画） |\\n| 小米TTS | 语音合成 |\\n| DeepSeek | 动态数据/题目生成 |\\n| 腾讯EdgeOne | 网站部署上线 |\\n| CapCut | 视频剪辑 |\\n| 剪映 | **声音克隆（核心大招）** |\\n\\n老李还是那个老李，他依然不会写代码。但万少帮他做到了——**在正确的时间，用正确的AI工具，解决正确的问题**。\\n\\n而这，也许就是2026年最重要的职场技能。\\n\\n---\\n\\n> **要是没有AI，万少是不想也不可能完成这个任务的。**\\n>\\n> 但有了AI，一切皆有可能。\\n\\n---\\n\\n*你用过哪些\\"救命\\"的AI工具？欢迎在评论区分享你的故事。*\\n\\n\\n\\n\\n\\n万少建立了一个专门讨论AI的微信群，大家可以互相交流和分享关于AI生态的资讯消息。\\n\\n目前人已经超过200人了，私聊我进群。\\n\\n关注我，持续分享鸿蒙开发 + AI 提效的实战技巧。\\n\\n![](assets/image-20260404153811993.DCT8eByA.png)\\n\\n"}`),A={name:"AI人工智能/要是没有AI 万少是不想也不可能完成这个任务的/要是没有AI 万少是不想也不可能完成这个任务的.md"};function I(m,n,h,c,_,C){return o(),e("div",null,[...n[0]||(n[0]=[p('<h1 id="万少用9个ai工具-帮朋友完成了一个-不可能-的项目" tabindex="-1">万少用9个AI工具，帮朋友完成了一个&quot;不可能&quot;的项目 <a class="header-anchor" href="#万少用9个ai工具-帮朋友完成了一个-不可能-的项目" aria-label="Permalink to &quot;万少用9个AI工具，帮朋友完成了一个&quot;不可能&quot;的项目&quot;">​</a></h1><blockquote><p><strong>要是没有AI，万少是不想也不可能完成这个任务的。</strong></p></blockquote><hr><p><img src="'+a+'" alt=""></p><h2 id="一、一个电话引发的-不可能任务" tabindex="-1">一、一个电话引发的&quot;不可能任务&quot; <a class="header-anchor" href="#一、一个电话引发的-不可能任务" aria-label="Permalink to &quot;一、一个电话引发的&quot;不可能任务&quot;&quot;">​</a></h2><p>上个月，万少的朋友老李突然给他打电话，声音里带着那种成年人特有的疲惫和焦虑。</p><p>&quot;兄弟，救命。&quot;</p><p>原来，他所在的集团突然下发了一个任务：每个子公司必须完成一个<strong>AI创新项目</strong>，而且要求全套交付——<strong>系统、文档、PPT、讲解视频</strong>，一样不能少。</p><p>老李在一家传统制造业公司干了十年，连Excel函数都用不利索，更别说做什么AI系统了。他跟万少说：&quot;集团领导说要&#39;拥抱人工智能&#39;，我连AI的A字怎么写都不知道。&quot;</p><p>更离谱的是，这个项目从下发到截止，<strong>只有两周时间</strong>。</p><p>老李知道万少平时爱玩AI、折腾各种新工具，于是把希望寄托在了万少身上。</p><p>万少听完沉默了五秒钟。</p><p>说实话，这个任务量——系统开发+数字人制作+文档+PPT+视频——放在以前，就算是一个专业团队也得折腾一个月。</p><p>但2026年了，AI工具已经多到眼花缭乱。也许，<strong>用AI工具链的组合，真的能在两周内搞定这一切</strong>？</p><p>于是，一场&quot;用AI造AI&quot;的疯狂实验，就这样开始了。</p><hr><h2 id="二、阶段一-ai系统开发——claude-code-kimi" tabindex="-1">二、阶段一：AI系统开发——Claude Code + Kimi <a class="header-anchor" href="#二、阶段一-ai系统开发——claude-code-kimi" aria-label="Permalink to &quot;二、阶段一：AI系统开发——Claude Code + Kimi&quot;">​</a></h2><h3 id="第一个问题-系统从哪来" tabindex="-1">第一个问题：系统从哪来？ <a class="header-anchor" href="#第一个问题-系统从哪来" aria-label="Permalink to &quot;第一个问题：系统从哪来？&quot;">​</a></h3><p>老李的项目需求很模糊——&quot;做一个AI智能问答系统&quot;。没有详细需求文档，没有设计稿，没有技术方案。</p><p>放在以前，这至少需要一个月的需求调研+技术选型+开发测试。</p><p>但现在，万少打开了 <strong>Claude Code</strong>。</p><p><img src="'+r+'" alt=""></p><p>Claude Code 是 Anthropic 推出的一款AI编程助手（基于命令行/IDE插件使用，上图为其官网），跟普通的聊天机器人不一样，它可以直接操作你的代码仓库、运行命令、读写文件。简单说，<strong>你说话，它写代码</strong>。</p><p>万少跟它说：&quot;帮我做一个AI智能问答网站，要有前端界面，能调用大模型API回答问题，界面要简洁美观。&quot;</p><p>二十分钟后，一个完整的项目骨架就出来了：React前端 + Node.js后端 + 大模型API对接。</p><p>但这还不够。万少需要让系统更&quot;智能&quot;——能处理文档上传、能记住对话历史、能根据上下文回答。</p><p>这时候，<strong>Kimi</strong> 登场了。</p><p><img src="'+s+'" alt="Kimi 界面"></p><p>Kimi 是国内月之暗面推出的大模型，它的特长是<strong>超长上下文</strong>——能一次性处理几十万字的文档。万少把 Claude 生成的代码丢给 Kimi，让它帮忙优化提示词工程、设计对话流程、甚至生成系统的知识库内容。</p><p><strong>Claude 负责&quot;搭骨架&quot;，Kimi 负责&quot;填血肉&quot;。</strong></p><hr><h2 id="三、阶段二-数字人制作——gpt-豆包-小米tts" tabindex="-1">三、阶段二：数字人制作——GPT + 豆包 + 小米TTS <a class="header-anchor" href="#三、阶段二-数字人制作——gpt-豆包-小米tts" aria-label="Permalink to &quot;三、阶段二：数字人制作——GPT + 豆包 + 小米TTS&quot;">​</a></h2><h3 id="第二个问题-集团要求-真人讲解视频" tabindex="-1">第二个问题：集团要求&quot;真人讲解视频&quot; <a class="header-anchor" href="#第二个问题-集团要求-真人讲解视频" aria-label="Permalink to &quot;第二个问题：集团要求&quot;真人讲解视频&quot;&quot;">​</a></h3><p>系统有了，但集团要求提交一段<strong>讲解视频</strong>——必须由项目负责人（也就是老李）出镜，介绍这个AI系统的功能和亮点。</p><p>老李跟万少说：&quot;让我对着镜头讲代码？不如杀了我。&quot;</p><p>确实，系统是万少做的，老李连系统里有几个页面都不知道，怎么讲？</p><p>但集团的要求很明确：<strong>真人声音+真人形象</strong>，要看到&quot;项目负责人亲自讲解&quot;。</p><p>于是万少想到了一个&quot;曲线救国&quot;的方案——<strong>数字人</strong>。</p><p><strong>第一步：生成数字人形象</strong></p><p>用 <strong>GPT</strong> 的图像生成功能，万少生成了一位&quot;专业、靠谱、看起来像在制造业干了十年的中年男性&quot;形象。为什么不用老李本人的照片？因为集团要求&quot;正式形象&quot;，而老李的微信头像还是五年前钓鱼时拍的。</p><p><strong>第二步：让图片动起来</strong></p><p>静态图片不行，要让它&quot;说话&quot;。万少用 豆包的图片转视频功能，把数字人图片做成了&quot;念字动画&quot;——就是嘴型会动、头会微微摆动的那种。</p><p><img src="'+i+'" alt=""></p><p><strong>第三步：给数字人配声音</strong></p><p>这是最关键的一步。视频需要&quot;老李的声音&quot;来讲解，但老李讲不出来。怎么办？</p><p>万少找到了 <strong>小米大模型的TTS（文本转语音）服务</strong>。小米给开发者提供了免费的token额度，只需要把讲解稿输入进去，它就能生成自然流畅的中文语音。</p><p><img src="'+u+'" alt=""></p><p>但这里有个问题：生成的声音是&quot;标准男声&quot;，不是老李的声音。</p><p>别急，后面有<strong>大招</strong>。</p><hr><h2 id="四、阶段三-智能数据生成——deepseek" tabindex="-1">四、阶段三：智能数据生成——DeepSeek <a class="header-anchor" href="#四、阶段三-智能数据生成——deepseek" aria-label="Permalink to &quot;四、阶段三：智能数据生成——DeepSeek&quot;">​</a></h2><h3 id="第三个问题-系统里要有-真实数据" tabindex="-1">第三个问题：系统里要有&quot;真实数据&quot; <a class="header-anchor" href="#第三个问题-系统里要有-真实数据" aria-label="Permalink to &quot;第三个问题：系统里要有&quot;真实数据&quot;&quot;">​</a></h3><p>一个AI问答系统，不能只有空壳子。集团领导万一要现场提问呢？系统必须能给出像模像样的回答。</p><p>但万少不可能手动录入几百条问答数据。</p><p>这时候，<strong>DeepSeek</strong> 派上了大用场。</p><p><img src="'+g+'" alt="DeepSeek 界面"></p><p>DeepSeek 是杭州深度求索推出的开源大模型，推理能力极强，网页版可以免费使用，API调用也有赠送额度。</p><p>万少设计了一个自动化流程：</p><ol><li>用 DeepSeek 生成&quot;制造业常见AI问答对&quot;——比如&quot;什么是智能质检&quot;、&quot;AI怎么优化排产&quot;等等</li><li>让 DeepSeek 根据每个问题生成<strong>专业、详细、有数据支撑</strong>的回答</li><li>把这些问答对自动写入系统的知识库</li></ol><p>一晚上，系统里多了<strong>800多条高质量问答数据</strong>，覆盖了智能制造、供应链优化、质量检测等十几个场景。</p><p>更绝的是，万少让 DeepSeek 生成了一套<strong>动态题目</strong>——如果集团领导要&quot;考&quot;这个系统，系统能随机生成专业问题并给出标准答案。</p><p>老李问万少：&quot;这些数据靠谱吗？&quot;</p><p>万少说：&quot;DeepSeek 写的，比你自己写的靠谱多了。&quot;</p><hr><h2 id="五、阶段四-一键部署——腾讯edgeone" tabindex="-1">五、阶段四：一键部署——腾讯EdgeOne <a class="header-anchor" href="#五、阶段四-一键部署——腾讯edgeone" aria-label="Permalink to &quot;五、阶段四：一键部署——腾讯EdgeOne&quot;">​</a></h2><p><img src="'+d+'" alt=""></p><h3 id="第四个问题-系统要能-现场演示" tabindex="-1">第四个问题：系统要能&quot;现场演示&quot; <a class="header-anchor" href="#第四个问题-系统要能-现场演示" aria-label="Permalink to &quot;第四个问题：系统要能&quot;现场演示&quot;&quot;">​</a></h3><p>集团评审是现场会，领导们会当场打开系统看效果。系统必须能<strong>稳定访问、快速加载、看起来专业</strong>。</p><p>万少原本打算部署到自己的服务器上，但担心现场网络环境复杂，万一打不开就全完了。</p><p>这时候，<strong>腾讯EdgeOne</strong> 派上了大用场。</p><p>EdgeOne 是腾讯推出的边缘计算和CDN服务，简单说就是：把你的网站部署到全国各地的服务器节点上，用户访问时自动连接到最近的一个，<strong>速度快、稳定性高</strong>。</p><p>更关键的是，它支持<strong>自动化部署</strong>。万少把代码推送到Git仓库，EdgeOne 自动拉取、构建、部署，整个过程相对快捷。</p><p>而且 EdgeOne 自带HTTPS证书、DDoS防护、访问统计——<strong>看起来就很&quot;企业级&quot;</strong>。</p><p>老李把系统链接发到集团群里的时候，附了一句：&quot;我们的AI系统已上线，欢迎体验。&quot;</p><p>三分钟后，集团IT部的人在群里回了一个大拇指。</p><hr><h2 id="六、阶段五-文档与视频自动化——kimi-capcut-剪映声音克隆" tabindex="-1">六、阶段五：文档与视频自动化——Kimi + CapCut + 剪映声音克隆 <a class="header-anchor" href="#六、阶段五-文档与视频自动化——kimi-capcut-剪映声音克隆" aria-label="Permalink to &quot;六、阶段五：文档与视频自动化——Kimi + CapCut + 剪映声音克隆&quot;">​</a></h2><h3 id="第五个问题-全套交付物怎么搞" tabindex="-1">第五个问题：全套交付物怎么搞？ <a class="header-anchor" href="#第五个问题-全套交付物怎么搞" aria-label="Permalink to &quot;第五个问题：全套交付物怎么搞？&quot;">​</a></h3><p>集团要求的是<strong>全套交付</strong>：系统、文档、PPT、讲解视频。</p><p>系统有了，但文档和PPT怎么办？让老李写？他连Markdown是什么都不知道。</p><p><strong>文档自动化：Kimi的&quot;一键生成&quot;</strong></p><p>万少把系统的代码结构、功能说明、技术架构截图发给 Kimi，让它帮忙生成：</p><ul><li>一份<strong>30页的技术白皮书</strong>（Word格式）</li><li>一份<strong>15页的汇报PPT</strong></li><li>一份<strong>5000字的项目总结</strong></li></ul><p>Kimi 花了大概十分钟，生成了全部内容。万少稍微调整了排版和格式，直接就能用。</p><p>老李看到文档的时候惊呆了：&quot;这写得比我自己还了解这个项目。&quot;</p><p>万少说：&quot;废话，这项目本来就是AI做的，AI当然最了解。&quot;</p><p><strong>视频制作：CapCut + 剪映</strong></p><p>现在到了最精彩的部分——<strong>讲解视频</strong>。</p><p>前面说了，万少用数字人+小米TTS生成了&quot;讲解音频&quot;，但声音不是老李本人的。集团要求&quot;项目负责人亲自讲解&quot;，如果声音明显不是他的，那就露馅了。</p><p>怎么办？</p><p><strong>剪映的声音克隆功能，成了整个项目的&quot;神来之笔&quot;。</strong></p><p><img src="'+q+'" alt="剪映/CapCut界面"></p><p>剪映（国内版，海外版叫CapCut）最近上线了<strong>声音克隆</strong>功能。万少只需要让老李对着手机念一段1-2分钟的样本文字，剪映就能<strong>克隆出他的声音</strong>——音色、语调、甚至说话的习惯性停顿，都模仿得惟妙惟肖。</p><blockquote><p><strong>技术伦理提示</strong>：声音克隆涉及个人声音权益，使用前需获得本人明确授权。本文所述场景已获得当事人同意，仅供技术探讨。</p></blockquote><p>然后，万少把之前用小米TTS生成的&quot;标准讲解稿&quot;，用剪映的<strong>声音克隆</strong>重新生成了一遍。</p><p>出来的效果？</p><p><strong>完全是老李在说话。</strong></p><p>万少把视频发给老李，老李听完回了三个问号：&quot;这他妈是我？？？&quot;</p><p>万少说：&quot;是&#39;你&#39;，但不是你说的。&quot;</p><p>最后，万少用 <strong>剪映（CapCut）</strong> 把数字人画面、克隆声音、系统录屏、字幕全部剪辑在一起，加了一个&quot;科技感&quot;的片头片尾。</p><p>一条<strong>5分钟的&quot;项目负责人亲自讲解AI系统&quot;视频</strong>，就这样诞生了。</p><hr><h2 id="八、写在最后" tabindex="-1">八、写在最后 <a class="header-anchor" href="#八、写在最后" aria-label="Permalink to &quot;八、写在最后&quot;">​</a></h2><p>回头看这个项目，万少用了<strong>9个AI工具</strong>：</p><table tabindex="0"><thead><tr><th>工具</th><th>用途</th></tr></thead><tbody><tr><td>Claude Code</td><td>开发AI系统</td></tr><tr><td>Kimi</td><td>代码优化、文档生成、PPT生成</td></tr><tr><td>GPT</td><td>数字人形象生成</td></tr><tr><td>即梦AI</td><td>图片转视频（念字动画）</td></tr><tr><td>小米TTS</td><td>语音合成</td></tr><tr><td>DeepSeek</td><td>动态数据/题目生成</td></tr><tr><td>腾讯EdgeOne</td><td>网站部署上线</td></tr><tr><td>CapCut</td><td>视频剪辑</td></tr><tr><td>剪映</td><td><strong>声音克隆（核心大招）</strong></td></tr></tbody></table><p>老李还是那个老李，他依然不会写代码。但万少帮他做到了——<strong>在正确的时间，用正确的AI工具，解决正确的问题</strong>。</p><p>而这，也许就是2026年最重要的职场技能。</p><hr><blockquote><p><strong>要是没有AI，万少是不想也不可能完成这个任务的。</strong></p><p>但有了AI，一切皆有可能。</p></blockquote><hr><p><em>你用过哪些&quot;救命&quot;的AI工具？欢迎在评论区分享你的故事。</em></p><p>万少建立了一个专门讨论AI的微信群，大家可以互相交流和分享关于AI生态的资讯消息。</p><p>目前人已经超过200人了，私聊我进群。</p><p>关注我，持续分享鸿蒙开发 + AI 提效的实战技巧。</p><p><img src="'+l+'" alt=""></p>',115)])])}const T=t(A,[["render",I]]);export{P as __pageData,T as default};
